# Generates the 13 original local cover illustrations (no external assets). Run: python3 tools/make-covers.py
import os
O = os.path.join(os.path.dirname(__file__), "..", "frontend", "public", "games")
T = lambda x, y, s, t, f="#fff", r=0, w=800: f'<text x="{x}" y="{y}" font-size="{s}" font-weight="{w}" font-family="Arial,Helvetica,sans-serif" fill="{f}" text-anchor="middle" transform="rotate({r} {x} {y})">{t}</text>'
R = lambda x, y, w, h, f, rx=14, o=1, r=0: f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{f}" opacity="{o}" transform="rotate({r} {x+w/2} {y+h/2})"/>'
C = lambda x, y, r, f, s="none", sw=0: f'<circle cx="{x}" cy="{y}" r="{r}" fill="{f}" stroke="{s}" stroke-width="{sw}"/>'
def cover(id, a, b, body):
    open(f"{O}/{id}.svg", "w").write(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 360"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{a}"/><stop offset="1" stop-color="{b}"/></linearGradient></defs><rect width="640" height="360" fill="url(#g)"/><circle cx="560" cy="50" r="90" fill="#fff" opacity=".07"/>{body}</svg>')
cover("daily", "#7c3aed", "#f59e0b", R(170,60,300,250,"#fff",22,.96)+R(170,60,300,64,"#f97316",22)+R(170,100,300,24,"#f97316",0)+C(215,60,9,"#fde68a")+C(425,60,9,"#fde68a")+"".join(C(210+c*50,160+r*45,8,"#c4b5fd" if (r+c)%4 else "#7c3aed") for r in range(3) for c in range(5))+C(450,262,66,"#5b21b6")+C(450,262,50,"none","#fde047",11).replace('stroke-width="11"','stroke-width="11" stroke-dasharray="210 110" stroke-linecap="round"')+T(450,283,60,"?","#fde047"))
cover("practice", "#0ea5e9", "#4f46e5", "".join(C(230,180,r,f) for r,f in [(125,"#fff"),(92,"#ef4444"),(60,"#fff"),(28,"#ef4444")])+'<path d="M300 90L232 178" stroke="#fde047" stroke-width="9" stroke-linecap="round"/><path d="M300 90l24-8-8 24z" fill="#fde047"/>'+"".join(R(400+i*18,70+i*70,190,64,"#fff",14,.95-i*.1)+f'<path d="M{420+i*18} {102+i*70}l12 12 24-26" stroke="#16a34a" stroke-width="9" fill="none" stroke-linecap="round"/>'+R(468+i*18,94+i*70,100,10,"#cbd5e1",5)+R(468+i*18,112+i*70,70,10,"#e2e8f0",5) for i in range(3)))
cover("trivia", "#4338ca", "#db2777", R(110,60,420,240,"#1e1b4b",22)+"".join(T(190+i*130,200,130,"?","#fde047" if i%2==0 else "#f0abfc") for i in range(3))+C(520,70,42,"#fde047")+R(508,108,24,18,"#fbbf24",4)+'<path d="M500 70h40M505 56l30 28M535 56l-30 28" stroke="#fff" stroke-width="3" opacity=".6"/>')
cover("emoji", "#ec4899", "#f97316", "".join(C(150+i*170,180,68,"#fde047","#f59e0b",5) for i in range(3))+C(125,165,8,"#422006")+C(175,165,8,"#422006")+'<path d="M118 200q32 34 64 0" stroke="#422006" stroke-width="8" fill="none" stroke-linecap="round"/>'+C(295,165,10,"#422006")+C(345,165,10,"#422006")+'<ellipse cx="320" cy="212" rx="14" ry="20" fill="#422006"/>'+C(465,165,8,"#422006")+'<path d="M505 165h22" stroke="#422006" stroke-width="8" stroke-linecap="round"/><path d="M458 205q32 28 64-6" stroke="#422006" stroke-width="8" fill="none" stroke-linecap="round"/>'+T(235,200,60,"+")+T(405,200,60,"="))
cover("riddle", "#6d28d9", "#0d9488", R(150,60,260,240,"#fff",22,.95,-5)+T(280,230,170,"?","#6d28d9",-5)+C(440,200,66,"rgba(255,255,255,.25)","#fde047",14)+'<path d="M488 248l62 64" stroke="#fde047" stroke-width="18" stroke-linecap="round"/>'+'<path d="M120 90l8 20 20 8-20 8-8 20-8-20-20-8 20-8z" fill="#fde047"/>')
cover("pattern", "#2563eb", "#10b981", '<polygon points="110,250 170,140 230,250" fill="#f97316"/>'+R(250,140,110,110,"#fde047",12)+C(445,195,56,"#ec4899")+'<polygon points="70,120 100,70 130,120" fill="#fff" opacity=".5"/>'+R(520,140,90,110,"none",12).replace('fill="none"','fill="rgba(255,255,255,.12)" stroke="#fff" stroke-width="5" stroke-dasharray="14 10"')+T(565,215,70,"?"))
cover("memory", "#059669", "#1d4ed8", "".join(R(130+c*130,50+r*90,110,76,col,16,1 if lit else .35)+(T(185+c*130,100+r*90,38,str(n)) if lit else "") for (r,c,col,lit,n) in [(0,0,"#f43f5e",1,1),(0,1,"#fde047",0,0),(0,2,"#38bdf8",1,2),(1,0,"#a78bfa",0,0),(1,1,"#22c55e",1,3),(1,2,"#f97316",0,0),(2,0,"#fde047",0,0),(2,1,"#38bdf8",0,0),(2,2,"#f43f5e",0,0)]))
cover("community", "#ea580c", "#be185d", "".join(R(90+i*140,70+(i%2)*30,170,210,c,18,1,-8+i*8)+C(150+i*140,130+(i%2)*30,22,"#fff")+R(115+i*140,175+(i%2)*30,120,12,"#fff",6,.8)+R(115+i*140,200+(i%2)*30,90,12,"#fff",6,.55) for i,c in enumerate(["#7c3aed","#0ea5e9","#16a34a"]))+C(540,70,36,"#fff")+'<path d="M540 90s-22-14-22-28a11 11 0 0122-4 11 11 0 0122 4c0 14-22 28-22 28z" fill="#ef4444" transform="translate(0 -4)"/>')
cover("math", "#dc2626", "#f59e0b", T(150,235,170,"7")+T(310,225,120,"×","#fde047")+T(470,235,170,"8")+"".join(R(30,80+i*48,150-i*20,8,"#fff",4,.55) for i in range(4))+'<polygon points="540,40 505,115 535,115 520,180 585,95 553,95" fill="#fde047"/>')
cover("oddone", "#0891b2", "#7e22ce", "".join(R(95+c*160,70+r*120,110,90,"#38bdf8",18) for r in range(2) for c in range(3) if (r,c)!=(1,1))+'<polygon points="320,190 336,222 372,227 346,252 352,288 320,271 288,288 294,252 268,227 304,222" fill="#fb923c" stroke="#fff" stroke-width="5"/>')
cover("scramble", "#eab308", "#7c3aed", "".join(R(70+i*130,110+(i%2)*40,100,110,"#fff",16,1,[-8,6,-4,9][i])+T(120+i*130,190+(i%2)*40,80,l,"#6d28d9",[-8,6,-4,9][i]) for i,l in enumerate("ODWR"))+'<path d="M150 70q170-50 340 0" stroke="#fff" stroke-width="7" fill="none" stroke-dasharray="4 14" stroke-linecap="round"/><path d="M490 70l-20-14M490 70l-22 10" stroke="#fff" stroke-width="7" stroke-linecap="round"/>')
