cover("saboteur", "#0f172a", "#0e7490", '<path d="M170 300V150" stroke="#67e8f9" stroke-width="8" stroke-linecap="round"/>'+C(170,140,14,"#22d3ee")+"".join(f'<path d="M{170+d*k} {140-d*.9*k}a{d*k*1.4} {d*k*1.4} 0 010 {d*k*1.8}" stroke="#22d3ee" stroke-width="6" fill="none" stroke-linecap="round" opacity="{1-i*.22}"/>' for i,k in enumerate([1,1.7,2.4]) for d in [28])+'<path d="M330 320c0-70 40-100 100-100s100 30 100 100z" fill="#020617"/>'+C(430,160,56,"#020617")+C(410,158,7,"#ef4444")+C(450,158,7,"#ef4444")+"".join(R(60+i*40,80+(i*37)%90,16,16,"#67e8f9",3,.5-.06*i) for i in range(5)))
